  // even though it's exactly the shape this utility exists to accept.
  sys?: { updatedAt?: string; [key: string]: unknown };
  fields: { regions?: ReadonlyArray<RegionRef> };
};

const isEligible = (entry: RegionAwareEntry, siteId: string): boolean => {
  const regions = entry.fields.regions;
  if (!regions || regions.length === 0) return true;
  return regions.some((region) => region.fields.siteId === siteId);
};

/** Fewer regions = more specific. Global/unscoped (empty or omitted) sorts last. */
const specificity = (entry: RegionAwareEntry): number =>
  entry.fields.regions && entry.fields.regions.length > 0 ? entry.fields.regions.length : Infinity;

/**
 * Inclusive filter — every entry eligible for `siteId` is kept, no precedence applied.
 * Use for arrays where multiple non-conflicting regional entries can legitimately
 * coexist in the same rendered list (e.g. links inside a shared navGroup).
 */
export function filterByRegion<T extends RegionAwareEntry>(entries: readonly T[], siteId: string): T[] {
  return entries.filter((entry) => isEligible(entry, siteId));
}

